using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;
class NativePluginShapes {
static string NativeRoot;static string Ide="C:\\Program Files\\Microsoft Visual Studio\\2022\\Community\\Common7\\IDE";
static Assembly Resolve(object sender,ResolveEventArgs e){string name=new AssemblyName(e.Name).Name+".dll";foreach(string dir in new[]{NativeRoot,Path.Combine(NativeRoot,"SourceLinks"),Ide,Path.Combine(Ide,"PublicAssemblies"),Path.Combine(Ide,"PrivateAssemblies")}){string p=Path.Combine(dir,name);if(File.Exists(p))return Assembly.ReflectionOnlyLoadFrom(p);}return Assembly.ReflectionOnlyLoad(e.Name);}
static int Main(string[] args){NativeRoot=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.ReflectionOnlyAssemblyResolve+=Resolve;var rows=new List<object>();foreach(string relative in new[]{"VaSourceLinksPluginApi.dll","SourceLinks\\FilePlugin.17.slp","SourceLinks\\UrlPlugin.slp","SourceLinks\\GitHubPlugin.17.slp","SourceLinks\\FogBugzPlugin.slp"}){string file=Path.Combine(NativeRoot,relative);var assembly=Assembly.ReflectionOnlyLoadFrom(file);Type[] types;var errors=new List<string>();try{types=assembly.GetTypes();}catch(ReflectionTypeLoadException error){types=error.Types.Where(x=>x!=null).ToArray();errors.AddRange(error.LoaderExceptions.Select(x=>x.Message));}var shapes=new List<object>();foreach(Type t in types){try{shapes.Add(new{type=t.FullName,isInterface=t.IsInterface,constructors=t.GetConstructors(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Select(x=>x.ToString()).ToArray(),interfaces=t.GetInterfaces().Select(x=>x.FullName).ToArray(),methods=t.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly).Select(x=>x.ToString()).ToArray(),properties=t.GetProperties().Select(x=>x.ToString()).ToArray(),fields=t.GetFields(BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly).Select(x=>x.ToString()).ToArray()});}catch(Exception error){errors.Add(t.FullName+": "+error.Message);}}string hash;using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();rows.Add(new{file,sha256=hash,reflectionOnly=true,shapes,errors});}File.WriteAllText(args[1],new JavaScriptSerializer{MaxJsonLength=16000000}.Serialize(rows));return 0;}}
